import type { Region } from "@workspace/api-zod/browser";
import type { LegalSource } from "./regional-legal-sources.js";
import { MATTER_SOURCE_GUIDANCE } from "./matter-source-guidance.js";

export type MatterAnswerAddition = {
  region: Region;
  service: string;
  problems: string[];
  id: string;
  en: { q: string; a: string };
  ar: { q: string; a: string };
  sources: LegalSource[];
  sourceLimitation?: string;
  sourceMethod?: "existing-explicit-guidance" | "primary-text" | "official-explanation";
};

const source = (href: string, en: string, ar: string): LegalSource => ({ href, en, ar });
const CIVIL = source("https://www.wipo.int/wipolex/ar/legislation/details/10917", "WIPO Lex — published Syrian Civil Code, Decree 84/1949", "ويبو لكس — القانون المدني السوري المنشور، المرسوم 84 لعام 1949");
const LABOUR = source("https://www.wipo.int/wipolex/en/legislation/details/10834", "WIPO Lex — Syrian Labour Law 17/2010", "ويبو لكس — قانون العمل السوري 17 لعام 2010");
const FAMILY = source("https://iimp.un.org/ar/node/693", "UN IIMP — Syrian family, guardianship and missing-person legal questions", "المؤسسة الأممية المستقلة للمفقودين — مسائل الأسرة والولاية والفقدان في سوريا");
const COMPANIES = source("https://alp.unescwa.org/sites/default/files/2021-09/Legislative%20Decree%20No.%2029%20of%202011%20on%20Companies%20Law_AR_reduce.pdf", "UN ESCWA — reproduced Syrian Companies Law 29/2011", "الإسكوا — نص قانون الشركات السوري 29 لعام 2011");
const COMPANY_FORMS = source("https://sana.sy/economy/2223713/", "SANA — company forms under Syrian Companies Law, 2025", "سانا — أشكال الشركات وفق قانون الشركات السوري، 2025");
const MEDICAL = source("https://sana.sy/locals/2526806/", "Syrian Prosecutor General — medical-liability framework, July 2026", "النائب العام السوري — إطار المسؤولية الطبية، تموز 2026");
const DEFENCE = source("https://sana.sy/locals/2556504/", "Syrian Deputy Justice Minister — defence, evidence and victim claims, August 2026", "معاون وزير العدل السوري — الدفاع والإثبات ومطالبات الضحايا، آب 2026");
const PROCEDURE_REPORT = source("https://docstore.ohchr.org/SelfServices/FilesHandler.ashx?enc=kj4VUyDaTcQ60jmcY7HKe3m2HsNlbCyjfzpHOax49BLvwE2GgydIIb4UKZEKegYDc9h%2FM748gOThsqzYC4KGQw%3D%3D", "Syrian state report CCPR/C/SYR/4 (2022), paragraphs 55, 60–62", "تقرير الدولة السورية CCPR/C/SYR/4 لعام 2022، الفقرات 55 و60–62");
const CIVIL_LIMIT = "Published 1949 Civil Code framework only. Current consolidation, relevant special law and the remedy in the particular matter still need verification; no numeric filing period is asserted.";
const LABOUR_LIMIT = "Source text is Labour Law17/2010 as reproduced by WIPO. Confirm coverage, subsequent amendments and current implementing instructions; public-service and overseas employment are not assumed covered.";

function add(region: Region, service: string, id: string, problems: string[], qEn: string, qAr: string, aEn: string, aAr: string, sources: LegalSource[], sourceLimitation?: string): MatterAnswerAddition {
  const sourceMethod = sources.some(item => /sana\.sy|thawra\.sy|arab-ency\.com\.sy|iimp\.un\.org/.test(item.href)) ? "official-explanation" : "primary-text";
  return { region, service, id, problems, en: { q: qEn, a: aEn }, ar: { q: qAr, a: aAr }, sources, sourceLimitation, sourceMethod };
}

function reuse(id: string, service: string, problems: string[], sourceLimitation?: string): MatterAnswerAddition {
  const existing = MATTER_SOURCE_GUIDANCE.find(item => item.id === id);
  if (!existing) throw new Error(`Missing expressly selected matter evidence: ${id}`);
  return { ...existing, service, problems, id: `${id}-answer-extension-${service}-${problems[0]}`, sourceLimitation, sourceMethod: "existing-explicit-guidance" };
}

